package kubesec

import (
	"bytes"
	"crypto/tls"
	"encoding/json"
	"io/ioutil"
	"mime/multipart"
	"net/http"
	"time"

	"github.com/ghodss/yaml"
	"github.com/vasu1124/introspect/pkg/logger"

	v1 "k8s.io/api/core/v1"
)

// Result represents a result returned by kubesec.io.
type Result struct {
	Error   string `json:"error"`
	Score   int    `json:"score"`
	Scoring struct {
		Critical []struct {
			Selector string `json:"selector"`
			Reason   string `json:"reason"`
			Weight   int    `json:"weight"`
		} `json:"critical"`
		Advise []struct {
			Selector string `json:"selector"`
			Reason   string `json:"reason"`
			Href     string `json:"href,omitempty"`
		} `json:"advise"`
	} `json:"scoring"`
}

// GetKubesecPod ...
func GetKubesecPod(pod *v1.Pod) (*Result, error) {
	yamlStr, err := yaml.Marshal(*pod)
	if err != nil {
		logger.Log.Error(err, "[kubesec] failure to marshall pod")
		return nil, err
	}

	return GetKubesecPodYAML(yamlStr)
}

// GetKubesecPodYAML ...
func GetKubesecPodYAML(yamlStr []byte) (*Result, error) {
	kubesecService := "https://v2.kubesec.io/scan"

	multif := &bytes.Buffer{}
	writer := multipart.NewWriter(multif)
	part, err := writer.CreateFormFile("uploadfile", "object.yaml")
	if err != nil {
		logger.Log.Error(err, "[kubesec] CreateFormFile failure")
		return nil, err
	}

	part.Write(yamlStr)
	writer.Close()

	req, err := http.NewRequest(http.MethodPost, kubesecService, multif)
	if err != nil {
		logger.Log.Error(err, "[kubesec] POST failure")
		return nil, err
	}
	req.Header.Add("Content-Type", writer.FormDataContentType())

	//	proxyURL, _ := url.Parse("http://127.0.0.1:8080")
	client := &http.Client{
		Timeout: time.Second * 3,
		Transport: &http.Transport{
			//Proxy: http.ProxyURL(proxyURL),
			TLSClientConfig: &tls.Config{
				InsecureSkipVerify: false,
			},
		},
	}

	resp, err := client.Do(req)
	if err != nil {
		logger.Log.Error(err, "[kubesec] client.Do failure")
		return nil, err
	}
	defer resp.Body.Close()

	if resp.StatusCode == http.StatusOK {
		body, err := ioutil.ReadAll(resp.Body)
		if err != nil {
			logger.Log.Error(err, "[kubesec] read body failure")
			return nil, err
		}
		var k Result
		if err := json.Unmarshal(body, &k); err != nil {
			logger.Log.Error(err, "[kubesec] Unmarshal body failure")
		}
		return &k, nil
		//fmt.Printf("response Body\n %v\n", k)
	}

	return nil, nil
}

package operator

import (
	"fmt"
	"html/template"
	"net/http"
	"os"

	"github.com/vasu1124/introspect/pkg/logger"
	uselessmachinev1alpha1 "github.com/vasu1124/introspect/pkg/operator/useless/api/v1alpha1"
	"github.com/vasu1124/introspect/pkg/operator/websocket"
	utilruntime "k8s.io/apimachinery/pkg/util/runtime"
	clientgoscheme "k8s.io/client-go/kubernetes/scheme"

	"github.com/olahol/melody"
	"github.com/vasu1124/introspect/pkg/operator/useless/controllers"
	"github.com/vasu1124/introspect/pkg/version"
	"k8s.io/apimachinery/pkg/runtime"
	controller_runtime "sigs.k8s.io/controller-runtime"
)

// Handler .
type Handler struct {
	Melody *melody.Melody
}

var (
	scheme = runtime.NewScheme()
)

func init() {
	utilruntime.Must(clientgoscheme.AddToScheme(scheme))
	utilruntime.Must(uselessmachinev1alpha1.AddToScheme(scheme))
	//+kubebuilder:scaffold:scheme
}

// New .
func New() *Handler {
	var h Handler

	h.Melody = melody.New()

	namespace, exists := os.LookupEnv("NAMESPACE")
	if !exists {
		namespace = "default"
	}

	controller_runtime.SetLogger(logger.Log)

	mgr, err := controller_runtime.NewManager(controller_runtime.GetConfigOrDie(), controller_runtime.Options{
		Scheme: scheme,
		// MetricsBindAddress:      "0", //turn off,
		LeaderElection:          true,
		LeaderElectionNamespace: namespace,
		LeaderElectionID:        "useless.introspect.actvirtual.com",
		Logger:                  controller_runtime.Log.WithName("operator"),
	})
	if err != nil {
		logger.Log.Error(err, "unable to start UselessMachine manager", "controller", "UselessMachine")
		return nil
	}

	if err = (&controllers.UselessMachineReconciler{
		Client:   mgr.GetClient(),
		Scheme:   mgr.GetScheme(),
		Notifier: websocket.NewNotifier(h.Melody, mgr.GetClient()),
	}).SetupWithManager(mgr); err != nil {
		logger.Log.Error(err, "[operator] unable to create controller", "controller", "UselessMachine")
		return nil
	}
	// +kubebuilder:scaffold:builder

	go func() {
		logger.Log.Info("[operator] starting manager")
		if err := mgr.Start(controller_runtime.SetupSignalHandler()); err != nil {
			logger.Log.Error(err, "[operator] problem running manager", "controller", "UselessMachine")
		}
	}()

	return &h
}

// ServeHTTP .
// This is an UI to the state of the Operator
func (h *Handler) ServeHTTP(w http.ResponseWriter, r *http.Request) {

	type EnvData struct {
		Version string
		Flag    bool
	}

	data := EnvData{version.Get().GitVersion, version.GetPatchVersion()%2 == 0}

	homeTemplate, err := template.ParseFiles("tmpl/layout.html", "tmpl/operator.html")
	if err != nil {
		fmt.Fprint(w, "[operator] parsing template: ", err)
		logger.Log.Error(err, "[operator] parsing template")
		return
	}

	err = homeTemplate.Execute(w, data)
	if err != nil {
		fmt.Fprint(w, "[operator] executing template: ", err)
		logger.Log.Error(err, "[operator] executing template")
	}

}

package server

import (
	"context"
	"fmt"
	"html/template"
	"net/http"
	"os"
	"time"

	"github.com/gorilla/mux"
	"github.com/prometheus/client_golang/prometheus/promhttp"
	"github.com/vasu1124/introspect/pkg/config"
	"github.com/vasu1124/introspect/pkg/cookie"
	"github.com/vasu1124/introspect/pkg/dynconfig"
	"github.com/vasu1124/introspect/pkg/election"
	"github.com/vasu1124/introspect/pkg/environ"
	"github.com/vasu1124/introspect/pkg/guestbook"
	"github.com/vasu1124/introspect/pkg/healthz"
	"github.com/vasu1124/introspect/pkg/logger"
	"github.com/vasu1124/introspect/pkg/mandelbrot"
	"github.com/vasu1124/introspect/pkg/middleware"
	"github.com/vasu1124/introspect/pkg/operator"
	"github.com/vasu1124/introspect/pkg/validate"
	"github.com/vasu1124/introspect/pkg/version"
)

// Server struct
type Server struct {
	router *mux.Router
}

// NewServer to get to a Server
func NewServer() *Server {
	srv := &Server{
		router: mux.NewRouter(),
	}

	return srv
}

// Run starts the Server
func (s *Server) Run(stop <-chan int) {
	s.registerHandlers()
	s.registerMiddlewares()

	srv := s.startServer()
	srvTLS := s.startServerTLS()

	// wait for Shutdown
	<-stop
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	logger.Log.Info("[server] Initiated graceful shutdown of HTTP(S) server")
	time.Sleep(1 * time.Second)

	if srv != nil {
		if err := srv.Shutdown(ctx); err != nil {
			logger.Log.Error(err, "[server] Graceful HTTP server shutdown failed")
		}
	}

	if srvTLS != nil {
		if err := srvTLS.Shutdown(ctx); err != nil {
			logger.Log.Error(err, "[server] Graceful HTTPS server shutdown failed")
		}
	}
}

func (s *Server) startServer() *http.Server {
	srv := &http.Server{
		Addr:         fmt.Sprintf(":%d", config.Default.Port),
		WriteTimeout: 30 * time.Second,
		ReadTimeout:  30 * time.Second,
		IdleTimeout:  60 * time.Second,
		Handler:      s.router,
	}

	go func() {
		logger.Log.Info("[server] Serving HTTP", "HTTP", srv.Addr)
		if err := srv.ListenAndServe(); err != http.ErrServerClosed {
			logger.Log.Error(err, "[server] HTTP server crashed")
		}
	}()

	return srv
}

func (s *Server) startServerTLS() *http.Server {
	if _, err := os.Stat("etc/tls/server.key"); err != nil {
		return nil
	}

	srv := &http.Server{
		Addr:         fmt.Sprintf(":%d", config.Default.SecurePort),
		WriteTimeout: 30 * time.Second,
		ReadTimeout:  30 * time.Second,
		IdleTimeout:  60 * time.Second,
		Handler:      s.router,
	}

	go func() {
		logger.Log.Info("[server] Serving HTTPS ", "HTTPS", srv.Addr)
		if err := srv.ListenAndServeTLS("etc/tls/server.crt", "etc/tls/server.key"); err != http.ErrServerClosed {
			logger.Log.Error(err, "[server] HTTPS server crashed")

		}
	}()

	return srv
}

func (s *Server) registerHandlers() {
	s.router.HandleFunc("/", serveMenu)
	logger.Log.Info("[server] registered /")
	s.router.HandleFunc("/favicon.ico", func(w http.ResponseWriter, r *http.Request) {
		http.ServeFile(w, r, "tmpl/favicon.ico")
	})
	logger.Log.Info("[server] registered /favicon.ico")
	s.router.PathPrefix("/css/").Handler(http.StripPrefix("/css/", http.FileServer(http.Dir("css"))))
	logger.Log.Info("[server] registered /css")
	s.router.HandleFunc("/mandelbrot/view", serveMandelbrotUI)
	logger.Log.Info("[server] registered /mandelbrot/view")
	s.router.Handle("/mandelbrot", mandelbrot.New())
	logger.Log.Info("[server] registered /mandelbrot")
	s.router.Handle("/environ", environ.New())
	logger.Log.Info("[server] registered /environ")
	s.router.Handle("/dynconfig", dynconfig.New())
	logger.Log.Info("[server] registered /dynconfig")
	s.router.Handle("/cookie", cookie.New())
	logger.Log.Info("[server] registered /cookie")
	s.router.Handle("/metrics", promhttp.Handler())
	logger.Log.Info("[server] registered /metrics")
	s.router.Handle("/validate", validate.New())
	logger.Log.Info("[server] registered /validate")
	s.router.Handle("/healthz", healthz.New())
	s.router.Handle("/healthzr", healthz.New())
	logger.Log.Info("[server] registered /healthz|r")
	gh := guestbook.New()
	s.router.Handle("/guestbook", gh)
	s.router.HandleFunc("/guestbook/switch", gh.SwitchHandler)
	logger.Log.Info("[server] registered /guestbook")
	s.router.Handle("/election", election.New())
	logger.Log.Info("[server] registered /election")
	o := operator.New()
	if o != nil {
		s.router.Handle("/operator", o)
		s.router.HandleFunc("/operatorws", func(w http.ResponseWriter, r *http.Request) {
			o.Melody.HandleRequest(w, r)
		})
		logger.Log.Info("[server] registered /operator")
	}

}

func (s *Server) registerMiddlewares() {
	s.router.Use(middleware.NewRequestLoggerHandler)
}

func serveMenu(w http.ResponseWriter, r *http.Request) {
	t, err := template.ParseFiles("tmpl/layout.html", "tmpl/menu.html")
	if err != nil {
		logger.Log.Error(err, "[server] template parse error")
		return
	}
	err = r.ParseForm()
	if err != nil {
		logger.Log.Error(err, "[server] ParseForm error")
	}

	type EnvData struct {
		Version string
		Flag    bool
	}
	data := EnvData{version.Get().GitVersion, version.GetPatchVersion()%2 == 0}

	err = t.Execute(w, data)
	if err != nil {
		logger.Log.Error(err, "[server] executing template")
		fmt.Fprint(w, "[server] executing template: ", err)
	}
}

func serveMandelbrotUI(w http.ResponseWriter, r *http.Request) {
